import re

def parse_size(text):
    pattern = r'^(\d+)([BKMGT])$'
    match = re.match(pattern, text)
    if not match:
        raise ValueError("Invalid input format")

    number, unit = match.groups()
    number = int(number)

    if unit == 'B':
        return number
    elif unit == 'KB':
        return number * 1024
    elif unit == 'MB':
        return number * 1024**2
    elif unit == 'GB':
        return number * 1024**3
    else:
        raise ValueError("Invalid unit")

import re

def parse_size(text):
    pattern = r'^(\d+)B$|^(\d+)KB$|^(\d+)MB$|^(\d+)GB$'
    match = re.match(pattern, text)
    if match:
        if match.group(1):
            return int(match.group(1))
        elif match.group(2):
            return int(match.group(2)) * 1024
        elif match.group(3):
            return int(match.group(3)) * 1024**2
        elif match.group(4):
            return int(match.group(4)) * 1024**3
    raise ValueError

import re

def compare_versions(a, b):
    version_pattern = re.compile(r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$')

    if not version_pattern.match(a) or not version_pattern.match(b):
        raise ValueError("Invalid version format")

    a_parts = list(map(int, a.split('.')))
    b_parts = list(map(int, b.split('.')))

    for i in range(3):
        if a_parts[i] < b_parts[i]:
            return -1
        elif a_parts[i] > b_parts[i]:
            return 1

    return 0

def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError
    result = []
    i = 0
    while i < len(s):
        count = 1
        while i + 1 < len(s) and s[i] == s[i + 1]:
            i += 1
            count += 1
        result.append(f"{s[i]}{count}")
        i += 1
    return ''.join(result)

